			data.if_listed_which_country_it_is_listed = grInd.if_listed_which_country_it_is_listed;	
			data.primary_country_of_assets = grInd.primary_country_of_assets.toString();
		  data.legal_postal_code = grInd.legal_postal_code.toString();
			data.legal_city = grInd.legal_city.toString();
			data.legal_country = grInd.legal_country.toString();		
			data.physical_street_address = grInd.physical_street_address.toString();				
			data.physical_postal_code = grInd.physical_postal_code.toString();
			data.physical_city = grInd.physical_city.toString();		
			data.physical_country = grInd.physical_country.toString();		
			data.total_assets = grInd.total_assets.toString();
			data.amount_in_usd = grInd.amount_in_usd.toString();		
			data.describe_the_source_of_annual_revenue = grInd.describe_the_source_of_annual_revenue.toString();				
			data.cheque_withdrawal = grInd.cheque_withdrawal.toString();
			data.atm_withdrawal = grInd.atm_withdrawal.toString();		
			data.ach_withdrawal = grInd.ach_withdrawal.toString();				
			data.cash_deposit = grInd.cash_deposit.toString();				
			data.as_of_date = grInd.as_of_date.toString();				
			data.amount_in_local_currency = grInd.amount_in_local_currency.toString();						
			data.annual_revenue = grInd.annual_revenue.toString();						
			data.estimated_annual_transaction_volume = grInd.estimated_annual_transaction_volume.toString();								
			data.describe_the_customer_significant_suppliers_free_text = grInd.describe_the_customer_significant_suppliers_free_text.toString();		
			data.countries_of_the_customer_s_significant_suppliers = grInd.countries_of_the_customer_s_significant_suppliers.toString();
			data.nature_of_business = grInd.nature_of_business.toString();								
			data.is_there_significant_private_ownership = grInd.is_there_significant_private_ownership;		

        }
	var form = $sp.getForm(table);


	console.log('Case Form - ' + JSON.stringify(form, null, 2));

})($sp);
